A.adt=new B.L(A.a3,"Severe Pseudomonas / Bone & Joint Infection (Adult PO)",A.U,null,null,null,750,null,null,null,null,null,A.I,A.aA,A.A,null,null,A.ey,null,null,A.w9,null,null,null,null,null,A.M,null,null,A.aYH,null,"High-dose oral therapy for severe Pseudomonas, osteomyelitis, or diabetic foot infections: 750 mg PO q12h.","\u0e15\u0e34\u0e14\u0e40\u0e0a\u0e37\u0e49\u0e2d Pseudomonas \u0e23\u0e38\u0e19\u0e41\u0e23\u0e07 / \u0e01\u0e23\u0e30\u0e14\u0e39\u0e01\u0e41\u0e25\u0e30\u0e02\u0e49\u0e2d (\u0e1c\u0e39\u0e49\u0e43\u0e2b\u0e0d\u0e48 PO): 750 mg PO \u0e17\u0e38\u0e01 12 \u0e0a\u0e21.",A.L,A.cv,null,null,null)
