A.adu=new B.L(A.a3,u.G,A.as,90,null,null,null,80,90,null,null,null,A.I,A.aA,A.cV,null,null,A.ex,A.iI,A.bjX,A.ac9,null,null,null,null,null,A.M,null,null,A.baf,null,"80-90 mg/kg/day divided q12h (45 mg/kg/dose) for Acute Otitis Media or resistant S. pneumoniae","\u0e02\u0e19\u0e32\u0e14\u0e22\u0e32\u0e2a\u0e39\u0e07 80\u201390 mg/kg/\u0e27\u0e31\u0e19 \u0e41\u0e1a\u0e48\u0e07\u0e43\u0e2b\u0e49\u0e17\u0e38\u0e01 12 \u0e0a\u0e21. (45 mg/kg/\u0e04\u0e23\u0e31\u0e49\u0e07) \u0e2a\u0e33\u0e2b\u0e23\u0e31\u0e1a\u0e2b\u0e39\u0e0a\u0e31\u0e49\u0e19\u0e01\u0e25\u0e32\u0e07\u0e2d\u0e31\u0e01\u0e40\u0e2a\u0e1a\u0e40\u0e09\u0e35\u0e22\u0e1a\u0e1e\u0e25\u0e31\u0e19 (AOM) \u0e2b\u0e23\u0e37\u0e2d\u0e1b\u0e2d\u0e14\u0e2d\u0e31\u0e01\u0e40\u0e2a\u0e1a",A.L,A.bo,null,null,null)
