A.agd=new B.L(A.aC,"Hemodynamic Support (Pediatric)",A.cs,null,null,null,null,null,null,2,20,"mcg/kg/min",A.d_,A.d0,A.A,A.da,null,A.ex,null,null,A.p6,null,null,null,1.6,null,A.b1,null,null,null,null,"Lexicomp Pediatric 2024 / AHA PALS: 2\u201320 mcg/kg/min IV continuous infusion (epinephrine/norepinephrine preferred first-line in pediatric septic shock).","\u0e1b\u0e23\u0e30\u0e04\u0e31\u0e1a\u0e1b\u0e23\u0e30\u0e04\u0e2d\u0e07\u0e01\u0e32\u0e23\u0e44\u0e2b\u0e25\u0e40\u0e27\u0e35\u0e22\u0e19\u0e40\u0e25\u0e37\u0e2d\u0e14 (\u0e40\u0e14\u0e47\u0e01): 2\u201320 mcg/kg/min IV \u0e2b\u0e22\u0e14\u0e15\u0e48\u0e2d\u0e40\u0e19\u0e37\u0e48\u0e2d\u0e07 (SSC \u0e41\u0e19\u0e30\u0e19\u0e33 Epinephrine/Norepinephrine \u0e40\u0e1b\u0e47\u0e19\u0e17\u0e32\u0e07\u0e40\u0e25\u0e37\u0e2d\u0e01\u0e41\u0e23\u0e01)",A.L,A.bo,null,null,null)
