A.adZ=new B.L(A.bh,"Cardiac Arrest \u2014 Pulseless VT/VF (Adult ACLS)",A.U,null,null,null,300,null,null,null,null,null,A.I,A.d1,A.A,null,null,A.ey,null,null,A.acc,null,null,null,null,null,A.b1,null,null,null,null,"AHA ACLS 2020 / Lexicomp DIH 2024: First dose 300 mg IV/IO bolus for shock-refractory VF/pVT; may repeat 150 mg once.","\u0e2b\u0e31\u0e27\u0e43\u0e08\u0e2b\u0e22\u0e38\u0e14\u0e40\u0e15\u0e49\u0e19 VF/pVT (\u0e1c\u0e39\u0e49\u0e43\u0e2b\u0e0d\u0e48 ACLS): \u0e42\u0e14\u0e2a\u0e41\u0e23\u0e01 300 mg IV/IO push (\u0e43\u0e2b\u0e49\u0e0b\u0e49\u0e33 150 mg \u0e44\u0e14\u0e49 1 \u0e04\u0e23\u0e31\u0e49\u0e07)",A.L,A.cv,null,null,null)
