A.bdB=s(["\u0e2b\u0e31\u0e27\u0e43\u0e08\u0e2b\u0e22\u0e38\u0e14\u0e40\u0e15\u0e49\u0e19\u0e0a\u0e31\u0e48\u0e27\u0e04\u0e23\u0e32\u0e27 / AV block (\u0e40\u0e01\u0e34\u0e14\u0e02\u0e36\u0e49\u0e19\u0e0a\u0e31\u0e48\u0e27\u0e04\u0e23\u0e39\u0e48\u0e2b\u0e25\u0e31\u0e07\u0e09\u0e35\u0e14)","\u0e2b\u0e25\u0e2d\u0e14\u0e25\u0e21\u0e2b\u0e14\u0e40\u0e01\u0e23\u0e47\u0e07\u0e23\u0e38\u0e19\u0e41\u0e23\u0e07\u0e43\u0e19\u0e1c\u0e39\u0e49\u0e1b\u0e48\u0e27\u0e22\u0e2b\u0e2d\u0e1a\u0e2b\u0e37\u0e14/\u0e16\u0e38\u0e07\u0e25\u0e21\u0e42\u0e1b\u0e48\u0e07\u0e1e\u0e2d\u0e07","\u0e2b\u0e31\u0e27\u0e43\u0e08\u0e40\u0e15\u0e49\u0e19\u0e0a\u0e49\u0e32\u0e2b\u0e23\u0e37\u0e2d\u0e2a\u0e31\u0e48\u0e19\u0e1e\u0e25\u0e34\u0e49\u0e27\u0e15\u0e48\u0e2d\u0e40\u0e19\u0e37\u0e48\u0e2d\u0e07"],t.s)
A.bry=s(["Dipyridamole (potentiates effect - reduce adenosine dose)","Theophylline / Caffeine (antagonizes effect - may need larger dose)"],t.s)
A.aip=new B.ak("adenosine","Adenosine",A.b8v,"\u0e2d\u0e30\u0e14\u0e35\u0e42\u0e19\u0e0b\u0e35\u0e19",A.cA,A.q,A.boP,null,A.a2,A.b1a,A.bny,A.bgV,A.bdG,A.bdB,null,!1,!1,!1,!0,null,null,A.bry,"Must be given as a RAPID IV push (1-2 seconds) followed immediately by a rapid normal saline flush.","\u0e15\u0e49\u0e2d\u0e07\u0e09\u0e35\u0e14 IV Push \u0e40\u0e23\u0e47\u0e27\u0e21\u0e32\u0e01\u0e46 (1-2 \u0e27\u0e34\u0e19\u0e32\u0e17\u0e35) \u0e41\u0e25\u0e49\u0e27\u0e15\u0e32\u0e21\u0e14\u0e49\u0e27\u0e22 Normal Saline \u0e17\u0e31\u0e19\u0e17\u0e35","Drug Information Handbook (Lexicomp/APhA) 2024 / AHA ACLS & PALS SVT Guidelines","2024-10-12",null,null,null,A.a_)
