A.aex=new B.L(A.a3,"Anaerobic Infection / Trichomoniasis (Adult)",A.U,null,null,null,400,null,null,null,null,null,A.I,A.bK,A.A,null,null,A.ey,null,null,A.DG,null,null,null,null,null,A.M,null,null,null,null,"Oral anaerobic infections / amoebiasis / trichomoniasis: 400\u2013500 mg PO q8h.","\u0e15\u0e34\u0e14\u0e40\u0e0a\u0e37\u0e49\u0e2d\u0e41\u0e1a\u0e04\u0e17\u0e35\u0e40\u0e23\u0e35\u0e22\u0e17\u0e35\u0e48\u0e44\u0e21\u0e48\u0e43\u0e0a\u0e49\u0e2d\u0e2d\u0e01\u0e0b\u0e34\u0e40\u0e08\u0e19 / \u0e1e\u0e22\u0e32\u0e18\u0e34\u0e0a\u0e48\u0e2d\u0e07\u0e04\u0e25\u0e2d\u0e14 (\u0e1c\u0e39\u0e49\u0e43\u0e2b\u0e0d\u0e48 PO): 400 mg PO \u0e17\u0e38\u0e01 8 \u0e0a\u0e21.",A.L,A.cv,null,null,null)
