A.aeN=new B.L(A.a3,"Clostridioides difficile Colitis (Adult PO)",A.U,null,null,null,500,null,null,null,null,null,A.I,A.bK,A.A,null,null,A.ey,null,null,A.aci,null,null,null,null,null,A.M,null,null,null,null,"Alternative non-severe C. difficile regimen when vancomycin/fidaxomicin are unavailable: 500 mg PO q8h for 10 days.","\u0e25\u0e33\u0e44\u0e2a\u0e49\u0e2d\u0e31\u0e01\u0e40\u0e2a\u0e1a C. difficile (\u0e17\u0e32\u0e07\u0e40\u0e25\u0e37\u0e2d\u0e01 \u0e1c\u0e39\u0e49\u0e43\u0e2b\u0e0d\u0e48 PO): 500 mg PO \u0e17\u0e38\u0e01 8 \u0e0a\u0e21. \u0e19\u0e32\u0e19 10 \u0e27\u0e31\u0e19",A.L,A.cv,null,null,null)
