A.adc=new B.L(A.a3,"Anaerobic Bacterial Infection (Pediatric PO)",A.as,30,null,null,null,20,40,null,null,null,A.I,A.bK,A.cV,null,null,A.ex,null,null,A.abC,null,null,null,null,null,A.M,null,null,null,null,"Pediatric oral anaerobic infections: 30 mg/kg/day PO divided q8h (10 mg/kg/dose; max 500 mg/dose, 2,000 mg/day).","\u0e15\u0e34\u0e14\u0e40\u0e0a\u0e37\u0e49\u0e2d\u0e41\u0e1a\u0e04\u0e17\u0e35\u0e40\u0e23\u0e35\u0e22\u0e17\u0e35\u0e48\u0e44\u0e21\u0e48\u0e43\u0e0a\u0e49\u0e2d\u0e2d\u0e01\u0e0b\u0e34\u0e40\u0e08\u0e19 (\u0e40\u0e14\u0e47\u0e01 PO): 30 mg/kg/\u0e27\u0e31\u0e19 \u0e41\u0e1a\u0e48\u0e07\u0e17\u0e38\u0e01 8 \u0e0a\u0e21. (10 mg/kg/\u0e04\u0e23\u0e31\u0e49\u0e07 \u0e2a\u0e39\u0e07\u0e2a\u0e38\u0e14 500 mg/\u0e04\u0e23\u0e31\u0e49\u0e07)",A.L,A.bo,null,null,null)
