A.aeT=new B.L(A.aC,"Traditional Dosing (Pediatric > 1 month)",A.as,2.5,null,null,null,2,2.5,null,null,null,A.I,A.bK,A.A,null,null,A.l3,null,null,A.abV,null,null,null,null,null,A.b1,30,null,null,null,"Lexicomp Pediatric 2024 / AAP Red Book: 6\u20137.5 mg/kg/day divided q8h (2\u20132.5 mg/kg/dose IV q8h); monitor peak/trough TDM.","\u0e40\u0e14\u0e47\u0e01 (> 1 \u0e40\u0e14\u0e37\u0e2d\u0e19) \u0e41\u0e1a\u0e1a\u0e41\u0e1a\u0e48\u0e07\u0e21\u0e37\u0e49\u0e2d: 2\u20132.5 mg/kg/\u0e04\u0e23\u0e31\u0e49\u0e07 IV \u0e17\u0e38\u0e01 8 \u0e0a\u0e21. (6\u20137.5 mg/kg/\u0e27\u0e31\u0e19); \u0e15\u0e34\u0e14\u0e15\u0e32\u0e21 Peak/Trough TDM",A.L,A.bo,null,null,null)
